const scenario=String($input.first().json.body?.scenario??"").trim();
const samples={
 standard:{leadId:"L-1001",fullName:"Mina Yilmaz",email:"mina@example.com",source:"website"},
 messy:{leadId:" L-1002 ",fullName:"  Jörg   Müller  ",email:" JOERG@EXAMPLE.COM ",source:" WEBSITE "},
 extra:{leadId:"L-1003",fullName:"Elif Kaya",email:"elif@example.com",source:"partner",internalSecret:"MUST_NOT_CROSS_CONTRACT",adminFlag:true},
 invalid:{leadId:"",fullName:"No Mail",email:"not-an-email",source:"website"}
};
if(!samples[scenario])return [{json:{scenario,validScenario:false,error:"unknown_scenario"}}];
return [{json:{scenario,validScenario:true,...samples[scenario]}}];

const child=$input.first().json;
const parent=$('Prepare Parent Input').item.json;
const parentKeys=Object.keys(parent).sort();
const childLeadKeys=Object.keys(child.lead??{}).sort();
const crossed=childLeadKeys.includes("internalSecret")||Object.prototype.hasOwnProperty.call(child,"internalSecret")||Object.prototype.hasOwnProperty.call(child,"adminFlag");
return [{json:{
 ok:true,module:"10",case:child.scenario,
 parentWorkflow:"BAIS Academy · Modul 10 · Sub-Workflow Architecture Lab",
 subworkflow:{name:"BAIS Academy · Modul 10 · Normalize Lead Contract",contractVersion:child.contractVersion,valid:child.valid,errors:child.errors,lead:child.lead},
 contract:{
  parentKeys,
  declaredInputs:child.contractFields,
  extraFieldCrossedBoundary:crossed,
  waitedForCompletion:true
 },
 architecture:{
  pattern:"orchestrator -> typed reusable sub-workflow -> normalized contract",
  benefit:"one component can be reused by multiple callers without copying normalization logic"
 },
 lesson:child.scenario==="extra"
  ?"Parent carried extra internal fields, but the declared workflow input mapping prevented them from crossing the sub-workflow contract."
  :child.scenario==="messy"
   ?"Normalization happened inside one reusable component, not copied into the parent."
   :child.scenario==="invalid"
    ?"The reusable component returned a stable validation contract instead of throwing uncontrolled business errors."
    :"Parent called a reusable database sub-workflow and waited for its typed result."
}}];
